import "server-only";
import { db } from "./db";
import { SHIPPING } from "./site";
import { gstIncluded } from "./money";

export type PricedLine = {
  productId: string;
  name: string;
  sku: string;
  image: string | null;
  unitPrice: number;
  quantity: number;
  gstRate: number;
  engravingText: string;
  stock: number;
  emiEligible: boolean;
};

export type Quote = {
  lines: PricedLine[];
  subtotal: number;
  discount: number;
  shippingFee: number;
  taxTotal: number;
  total: number;
  coupon: { id: string; code: string } | null;
  couponError: string | null;
  emiEligible: boolean;
};

/**
 * Single source of truth for order totals. Prices always come from the database —
 * the client only ever sends product ids and quantities.
 */
export async function priceCart(
  items: { productId: string; quantity: number; engravingText: string }[],
  couponCode?: string | null,
): Promise<Quote> {
  const products = await db.product.findMany({
    where: { id: { in: items.map((i) => i.productId) }, isActive: true },
    include: { images: { orderBy: { sortOrder: "asc" }, take: 1 } },
  });
  const byId = new Map(products.map((p) => [p.id, p]));

  const lines: PricedLine[] = [];
  for (const item of items) {
    const p = byId.get(item.productId);
    if (!p) continue;
    lines.push({
      productId: p.id,
      name: p.name,
      sku: p.sku,
      image: p.images[0]?.url ?? null,
      unitPrice: p.price,
      quantity: item.quantity,
      gstRate: p.gstRate,
      engravingText: p.engravingAvailable ? item.engravingText : "",
      stock: p.stock,
      emiEligible: p.emiEligible,
    });
  }

  const subtotal = lines.reduce((s, l) => s + l.unitPrice * l.quantity, 0);

  let discount = 0;
  let coupon: Quote["coupon"] = null;
  let couponError: string | null = null;
  if (couponCode) {
    const c = await db.coupon.findUnique({ where: { code: couponCode.trim().toUpperCase() } });
    const now = new Date();
    if (!c || !c.isActive) couponError = "This coupon code is not valid.";
    else if (c.validFrom && c.validFrom > now) couponError = "This coupon is not active yet.";
    else if (c.validTo && c.validTo < now) couponError = "This coupon has expired.";
    else if (c.usageLimit !== null && c.usedCount >= c.usageLimit) couponError = "This coupon has been fully redeemed.";
    else if (subtotal < c.minOrderAmount) couponError = `Add items worth ₹${Math.ceil((c.minOrderAmount - subtotal) / 100)} more to use this coupon.`;
    else {
      discount = c.type === "PERCENT" ? Math.round((subtotal * c.value) / 100) : c.value;
      if (c.maxDiscount !== null) discount = Math.min(discount, c.maxDiscount);
      discount = Math.min(discount, subtotal);
      coupon = { id: c.id, code: c.code };
    }
  }

  const afterDiscount = subtotal - discount;
  const shippingFee = lines.length === 0 || afterDiscount >= SHIPPING.freeAbove ? 0 : SHIPPING.flatFee;
  // GST is included in selling prices; apportion the discount proportionally for the tax figure.
  const ratio = subtotal ? afterDiscount / subtotal : 0;
  const taxTotal = lines.reduce((s, l) => s + gstIncluded(Math.round(l.unitPrice * l.quantity * ratio), l.gstRate), 0);

  return {
    lines,
    subtotal,
    discount,
    shippingFee,
    taxTotal,
    total: afterDiscount + shippingFee,
    coupon,
    couponError,
    emiEligible: lines.some((l) => l.emiEligible),
  };
}
